script:
export const meta = {
  name: 'review_loop',
  description: 'Actor-Critic review→fix→re-review loop with per-file chunked fan-out, adversarial verification, severity gating, bounded convergence',
  phases: [{ title: 'Scope' }, { title: 'Converge' }, { title: 'Report' }],
}

// ---- Config (overridable via args; CLI key=value arrive as strings) ----
const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d }
const consecutiveEmpty = 2 // dry rounds loopUntilDry must observe before it may certify convergence
const scope         = (args && args.scope) || (args && args._) || 'the current branch vs its merge-base with main, else staged, else HEAD'
const maxRounds     = num(args && args.maxRounds, 5)
const reviewers     = num(args && args.reviewers, 2)
const threshold     = num(args && args.threshold, 0.5)
// Per-chunk TARGET size (not a hard ceiling): each critic lane reviews at most ~this many diff lines.
const chunkTarget   = num((args && args.chunkTargetLines) || (args && args.maxChunkLines), 400)
const maxChunks     = Math.max(1, num(args && args.maxChunks, 12))   // HARD cap on chunks so chunks*lanes agents stay bounded
let gate = (args && args.severityGate) || ['blocker', 'high']
if (typeof gate === 'string') gate = gate.split(',').map((s) => s.trim()).filter(Boolean)

const findingSchema = {
  type: 'object',
  properties: { findings: { type: 'array', items: { type: 'object', properties: {
    id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'high', 'medium', 'suggestion'] },
    category: { type: 'string', enum: ['security', 'correctness', 'performance', 'maintainability'] },
    location: { type: 'string' }, description: { type: 'string' }, evidence: { type: 'string' },
    repro_test: { type: 'string' }, boundary_owner: { type: 'string', enum: ['current', 'server', 'external'] },
    confidence: { type: 'string', enum: ['low', 'medium', 'high'] },
  }, required: ['id', 'severity', 'category', 'location', 'description', 'boundary_owner'] } } },
  required: ['findings'],
}

// Stable identity + de-duplication. Two keys on purpose:
//  - keyOf (category+location) is the TIGHT loop-identity key: critic-assigned ids are
//    non-deterministic across rounds, so loopUntilDry keys on it to detect
//    no-progress / oscillation (duplicate-only rounds are dry). Keying on f.id would let
//    the same logical finding recur under a fresh id every round and defeat that.
//  - reportKeyOf adds a description fingerprint so the REPORT dedup does not
//    silently merge two genuinely different issues at the same location.
const keyOf = (f) => (f.category || '?') + '|' + (f.location || '?')
const fp = (s) => { let h = 0; const str = String(s || ''); for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) | 0 } return h }
const reportKeyOf = (f) => keyOf(f) + '|' + fp(f.description)
const dedupBy = (arr, keyFn) => {
  const seen = {}
  const out = []
  for (const f of arr) { const k = keyFn(f); if (!seen[k]) { seen[k] = true; out.push(f) } }
  return out
}

// Shell-quote a path so an attacker-influenced filename in the reviewed diff (git
// filenames may contain spaces, ;, $(), backticks, #, quotes) cannot break out of
// the `git diff ... -- <path>` argument list and inject commands into a lane's shell.
const shq = (p) => "'" + String(p).replace(/'/g, "'\\''") + "'"

const laneNames = ['maintainability', 'correctness', 'security']
const laneCount = laneNames.length

// ---- Phase 1: resolve scope + per-file sizes, then pack into bounded chunks ----
phase('Scope')
const scan = await agent(
  'Resolve review scope: ' + scope + '. Determine the git diff command (e.g. "git diff main...HEAD", ' +
  '"git diff --staged", or "git show HEAD") WITHOUT file paths, and list changed files with each file\'s ' +
  'added+removed line count. Return diffCmd, files [{path, lineCount}], and totalLines.',
  { tier: 'small', label: 'scope + sizes', schema: { type: 'object', properties: {
      diffCmd: { type: 'string' },
      files: { type: 'array', items: { type: 'object', properties: { path: { type: 'string' }, lineCount: { type: 'number' } }, required: ['path', 'lineCount'] } },
      totalLines: { type: 'number' }
    }, required: ['diffCmd', 'files', 'totalLines'] } })
if (!scan || typeof scan.diffCmd !== 'string' || !Array.isArray(scan.files)) {
  return { verdict: 'ABORTED — could not resolve scope/diff', roundsRun: 0, chunks: 0, oversizedFiles: [],
           totalAddressed: 0, totalResolved: 0, unresolved: [], unverified: [], disputed: [], tracked: [], trajectory: [],
           report: 'Scope agent returned no usable file list.' }
}

// Pack files into <= maxChunks chunks, each ~chunkTarget lines (a lone oversized file gets its own chunk).
const perChunk = Math.max(chunkTarget, Math.ceil((scan.totalLines || 1) / maxChunks))
const chunks = []
let cur = [], curLines = 0
for (const f of scan.files) {
  if (cur.length && curLines + f.lineCount > perChunk) { chunks.push(cur); cur = []; curLines = 0 }
  cur.push(f); curLines += f.lineCount
}
if (cur.length) chunks.push(cur)
// HARD cap: first-fit fragmentation can produce MORE than maxChunks chunks (each file
// alone < perChunk but any two together > perChunk). Since each chunk spawns lanes*reviewers
// agents, enforce the documented bound by merging the overflow into the final chunk.
if (chunks.length > maxChunks) {
  const merged = chunks.slice(0, maxChunks - 1)
  merged.push(chunks.slice(maxChunks - 1).flat())
  chunks.length = 0
  for (const c of merged) chunks.push(c)
}
const oversizedFiles = scan.files.filter((f) => f.lineCount > perChunk).map((f) => f.path)
log('scope: ' + scan.files.length + ' files, ' + scan.totalLines + ' lines -> ' + chunks.length + ' chunk(s) of ~' + perChunk + ' lines')

const RULES =
  ' RULES: Comment ONLY on the files in this chunk plus at most one hop of direct dependencies. Flag issues; do NOT rewrite code. ' +
  'Severity blocker/high = crashes, security, logic bugs, measurable perf/arch regressions; medium/suggestion = style, micro-opts, speculative edge cases. ' +
  'Set boundary_owner=current only if the fix belongs in THIS diff. For every blocker/high include a concrete repro_test that fails on current behavior. Quote evidence.'

// One critic lane over one chunk: fetches its own scoped diff via git (keeps context small & high-signal).
// Paths are shell-quoted (shq) so untrusted filenames cannot inject shell commands.
const laneOnChunk = (persona, tier, paths, tag) =>
  agent(persona + ' Obtain this chunk\'s diff by running: ' + scan.diffCmd + ' -- ' + paths.map(shq).join(' ') +
        '\nReview only those files (+ one hop).' + RULES,
        { tier, label: tag, schema: findingSchema })

// ---- Phase 2: bounded Actor-Critic convergence loop (chunked fan-out per round) ----
phase('Converge')
let lastSurvivors = []
let roundsRun = 0
const tracked = []
const unverified = [] // missing/partial verifier coverage — escalated, never silently dropped
const disputed = []   // split verifier votes — escalated, never silently dropped
const fixLog = []
const trajectory = []
// convergence evidence must track CLEAN post-fix critic rounds, not loopUntilDry's dedup
// state: a duplicate survivor still runs the fixer this round, so it is NOT dry. Increment
// only when THIS round produced zero survivors so a single empty review cannot combine with
// a still-failing round to falsely certify CONVERGED CLEAN.
let convergedDry = 0
const recordRound = (arr) => { if ((arr || []).length) convergedDry = 0; else convergedDry++; return arr }

const found = await loopUntilDry({
  maxRounds, consecutiveEmpty, key: keyOf,
  round: async (r) => {
    roundsRun = r + 1
    // CRITIC: fan out chunks x lanes; each lane isolated + scope-locked to its chunk.
    const perChunkResults = await parallel(chunks.map((chunk, ci) => async () => {
      const paths = chunk.map((f) => f.path)
      const lanes = await parallel([
        () => laneOnChunk('Read the skill file at ~/.agents/skills/thermo-nuclear-code-quality-review/SKILL.md (expand ~ to your home dir) and apply it as a MAINTAINABILITY critic.',
                          'big', paths, 'maint c' + ci + ' r' + roundsRun),
        () => laneOnChunk('You are a CORRECTNESS critic: trace critical paths; logic bugs, missing authz, boundary/edge errors.',
                          'big', paths, 'correct c' + ci + ' r' + roundsRun),
        () => laneOnChunk('You are a SECURITY critic: injection, secrets, authz, unsafe handling of untrusted input.',
                          'big', paths, 'sec c' + ci + ' r' + roundsRun),
      ])
      return { lanes, findings: lanes.filter(Boolean).flatMap((l) => (l && l.findings) || []) }
    }))
    const all = perChunkResults.flatMap((x) => x.findings)
    // Record missing coverage: a lane that returned null did not review its chunk.
    const totalLanes = chunks.length * laneCount
    const lanesOk = perChunkResults.reduce((n, x) => n + x.lanes.filter(Boolean).length, 0)

    // CLASSIFY: loop-drivers vs tracked-for-later
    const gated = []
    for (const f of all) {
      if (gate.indexOf(f.severity) >= 0 && f.boundary_owner === 'current') gated.push(f)
      else tracked.push(f)
    }
    if (!gated.length) {
      trajectory.push({ round: roundsRun, lanesOk, totalLanes, findings: all.length, gated: 0, survivors: 0, unverified: 0, fixed: 0, applied: null, testsPass: null })
      lastSurvivors = []
      return recordRound([])
    }

    // VERIFY: adversarial skeptics must REFUTE; only survivors proceed.
    const checks = await parallel(gated.map((f) => () =>
      verify('Category ' + f.category + ' at ' + f.location + ': ' + f.description +
             '\nClaimed repro: ' + (f.repro_test || '(none)') +
             '\nREAL only if the repro would truly fail on current behavior and the fix belongs in this diff.',
             { reviewers, threshold, lens: [f.category, 'is this edge case already implicitly handled?'] })))
    // A NULL or PARTIAL verify is missing coverage, NOT a refutation; a split vote is
    // DISPUTED. Escalate both rather than silently dropping a possibly-real blocker.
    const survivors = []
    let unverifiedThisRound = 0
    gated.forEach((f, i) => {
      const c = checks[i]
      const covered = c && typeof c.total === 'number' ? c.total : 0
      if (!c || covered < reviewers) { unverified.push(f); unverifiedThisRound++; log('Verification incomplete for ' + keyOf(f) + ' in round ' + roundsRun + ' (covered ' + covered + '/' + reviewers + '); routing to human escalation (not silently dropped).') }
      else if (c.real) survivors.push(f)
      else if ((c.realCount || 0) > 0) { disputed.push(f); log('Finding ' + keyOf(f) + ' DISPUTED in round ' + roundsRun + ' (' + c.realCount + '/' + c.total + ' reviewers voted real); escalating (not dropped).') }
    })
    lastSurvivors = survivors
    if (!survivors.length) {
      trajectory.push({ round: roundsRun, lanesOk, totalLanes, findings: all.length, gated: gated.length, survivors: 0, unverified: unverifiedThisRound, fixed: 0, applied: null, testsPass: null })
      return recordRound([])
    }

    // ACTOR: single fixer holds fix authority; fixes survivors ONLY, adds failing->passing tests, stays in scope.
    const fix = await agent(
      'You are the fixer. Apply MINIMAL fixes for ONLY these verified blockers, add a test that fails before / passes after each, ' +
      'stay within the diff scope, then report what changed.\n\n' + JSON.stringify(survivors),
      { tier: 'big', label: 'fix r' + roundsRun })

    // VALIDATE: independently confirm the fixes actually landed and tests pass, so the
    // reported metric is resolution ("did it get fixed?"), not merely "handed to the fixer".
    // A null validation is missing coverage, not success.
    const validation = await agent(
      'You are the validator. The fixer just applied fixes for these findings:\n' + JSON.stringify(survivors) +
      '\n\nFixer report:\n' + String(fix) +
      '\n\nIndependently confirm via git/tooling that the intended changes are present in the working tree, then run the project test/build command. ' +
      'Return applied (were the intended changes made) and testsPass (did the suite/build pass).',
      { tier: 'medium', label: 'validate r' + roundsRun, schema: { type: 'object', properties: {
          applied: { type: 'boolean' }, testsPass: { type: 'boolean' }, notes: { type: 'string' } }, required: ['applied', 'testsPass'] } })
    if (!validation) log('Validation returned null in round ' + roundsRun + '; fix landing/tests UNCONFIRMED.')
    const applied = validation ? validation.applied : null
    const testsPass = validation ? validation.testsPass : null

    trajectory.push({ round: roundsRun, lanesOk, totalLanes, findings: all.length, gated: gated.length, survivors: survivors.length, unverified: unverifiedThisRound, fixed: survivors.length, applied, testsPass })
    fixLog.push({ round: roundsRun, fixed: survivors.length, applied, testsPass, findings: survivors, summary: fix, validationNotes: validation && validation.notes })
    return recordRound(survivors)
  },
})

// ---- Phase 3: report + verdict + escalation ----
phase('Report')
const trackedUnique = dedupBy(tracked, reportKeyOf)
const unverifiedUnique = dedupBy(unverified, reportKeyOf)
const disputedUnique = dedupBy(disputed, reportKeyOf)
const totalAddressed = found.length
// Resolution counts UNIQUE findings whose fixes were validated as landed + passing.
// A finding still surfacing as a survivor at loop end is NOT resolved even if an
// earlier round's validation passed (the fix did not hold).
const unresolvedKeys = {}
for (const f of lastSurvivors) unresolvedKeys[keyOf(f)] = true
const resolvedKeys = {}
for (const e of fixLog) {
  if (e.applied === true && e.testsPass === true) {
    for (const f of (e.findings || [])) { const k = keyOf(f); if (!unresolvedKeys[k]) resolvedKeys[k] = true }
  }
}
const totalResolved = Object.keys(resolvedKeys).length

// Coverage-aware clean verdict: a round that returns [] is NOT clean if the critic
// lanes did not fully cover it, and "clean" must also account for blockers we could
// not verify or fixes we could not confirm landed.
const terminal = trajectory.slice(-2)
const coverageComplete = terminal.length > 0 && terminal.every((t) => t.lanesOk === t.totalLanes)
const unconfirmedFixes = fixLog.filter((e) => e.applied !== true || e.testsPass !== true)
// Only certify convergence when the loop genuinely reached the required consecutive
// dry rounds; otherwise it stopped at the round cap.
const converged = convergedDry >= consecutiveEmpty

const verdict =
    (lastSurvivors.length > 0 && roundsRun >= maxRounds) ? 'STOPPED AT CAP — escalate to human'
  : (lastSurvivors.length === 0 && !converged) ? ('STOPPED AT CAP — did not reach ' + consecutiveEmpty + ' consecutive dry rounds; do NOT treat as clean, escalate to human')
  : (lastSurvivors.length === 0 && disputedUnique.length > 0) ? ('CONVERGED w/ DISPUTED — ' + disputedUnique.length + ' finding(s) had split verifier votes; escalate to human')
  : (lastSurvivors.length === 0 && !coverageComplete) ? 'INCONCLUSIVE — incomplete critic coverage; do NOT treat as clean, escalate to human'
  : (lastSurvivors.length === 0 && unverifiedUnique.length > 0) ? ('CONVERGED w/ UNVERIFIED — ' + unverifiedUnique.length + ' finding(s) could not be verified; escalate to human')
  : (lastSurvivors.length === 0 && unconfirmedFixes.length > 0) ? ('CONVERGED w/ UNCONFIRMED FIXES — ' + unconfirmedFixes.length + ' fix round(s) had unconfirmed landing/tests; do NOT treat as clean, escalate to human')
  : lastSurvivors.length === 0 ? 'CONVERGED CLEAN'
  : 'STOPPED — no new blockers (possible oscillation on remaining items)'

const report = await agent(
  'Write a concise final report: verdict, chunking summary, per-round trajectory, resolution rate (validated-resolved/total gated), ' +
  'fixes whose landing or tests were NOT confirmed, unresolved blockers to escalate, findings that could NOT be verified (escalate to human), ' +
  'disputed findings (split verifier votes — escalate), and the tracked-for-later list. Do NOT re-litigate resolved items.\n\n' +
  'VERDICT: ' + verdict + '\nCHUNKS: ' + chunks.length + ' (~' + perChunk + ' lines each)' +
  '\nOVERSIZED FILES (single-file context risk): ' + JSON.stringify(oversizedFiles) +
  '\nROUNDS: ' + roundsRun +
  '\nADDRESSED (handed to fixer): ' + totalAddressed + '\nRESOLVED (validated landed + tests pass): ' + totalResolved +
  '\nTRAJECTORY:\n' + JSON.stringify(trajectory) +
  '\nFIX LOG:\n' + JSON.stringify(fixLog) +
  '\nUNRESOLVED:\n' + JSON.stringify(lastSurvivors) +
  '\nUNVERIFIED (verification failed — escalate):\n' + JSON.stringify(unverifiedUnique) +
  '\nDISPUTED (split verifier votes — escalate):\n' + JSON.stringify(disputedUnique) +
  '\nTRACKED:\n' + JSON.stringify(trackedUnique),
  { tier: 'medium', label: 'synthesis' })

return { verdict, roundsRun, chunks: chunks.length, oversizedFiles, totalAddressed, totalResolved, totalFixed: totalAddressed, unresolved: lastSurvivors, unverified: unverifiedUnique, disputed: disputedUnique, tracked: trackedUnique, trajectory, report }
